      .layer(window.osc(8, 0.1, 2).mask(window.shape(4, 0.3, 1e-6)), 0.1)
      .out();

  } catch (error) {
    console.error('Hydra error:', error);
    container.innerHTML = `&lt;div style="display: flex; align-items: center; justify-content: center; height: 100%; color: #666; font-size: 14px; background: linear-gradient(45deg, #f8f9fa, #e9ecef); border-radius: 8px; font-family: system-ui, sans-serif;"&gt;Interactive Hydra visualization&lt;br&gt;&lt;small style="opacity: 0.7;"&gt;Loading...&lt;/small&gt;&lt;/div&gt;`;
  }

  return container;
}

canvas = {
  const S = config.size;
  const concurrency = config.concurrency;
  const context = DOM.context2d(S, S);
  paper.setup(context.canvas);
  paper.view.viewSize = new paper.Size(S, S);

  const lines = data.lines.reverse();
  let paths = [];
  let i = 0;
  let fillColor;
  const reset = () =&gt; {
    paper.project.activeLayer.removeChildren();
    const backgroundLayer = new paper.Layer();
    const background = new paper.Path.Rectangle(paper.view.bounds);
    const colorIdx = Math.floor(Math.random() * config.colors.length);
    fillColor = fillColorByArea(config.colors[colorIdx]);
    background.style = { fillColor: config.colors[colorIdx].bgColor };
    paper.view.draw();
    i = 0;
  };
  const animate = lines =&gt; {
    paths = [];
    i = 0;
    const b = bounds(lines);
    const scaleX = d3
      .scaleLinear()
      .domain([b[0], b[2]])
      .range([10, S - 10]);
    const scaleY = d3
      .scaleLinear()
      .domain([b[1], b[3]])
      .range([10, S - 10]);
    return () =&gt; {
      if (i &gt; lines.length / concurrency) return;
      for (let batch = 0; batch &lt; concurrency; batch++) {
        const pos = batch * Math.floor(lines.length / concurrency) + i;
        if (!lines[pos]) continue;
        const path = new paper.Path({
          segments: [],
          strokeColor: 'white'
        });
        lines[pos].forEach(point =&gt; {
          path.add(new paper.Point(scaleX(point.x), scaleY(point.y)));
        });
        if (Math.abs(path.area) &lt; 10) continue;
        path.fillColor = fillColor(path);
        paths.push(path);
      }
      i++;
    };
  };
  reset();
  context.canvas.onclick = reset;
  paper.view.onFrame = animate(lines);

  return context.canvas;
}

config = {
  return {
    size: 600,
    concurrency: 4,
    colors: [
